import json
for f in ['/tmp/end.json','/tmp/terminate.json','/tmp/delay.json']:
    d = json.load(open(f))
    node = d.get('Data',{}).get('Node', d.get('Data', d))
    print(f, '->', node.get('nodeType'), node.get('version'))
    for h in node.get('handleConfiguration', []):
        for handle in h.get('handles', []):
            print('   handle:', handle.get('id'), handle.get('handleType'))
"

